    49  zip_source_t *
    50  zip_source_layered_create(zip_source_t *src, zip_source_layered_callback cb, void *ud, zip_error_t *error) {
    51      zip_source_t *zs;
    52      zip_int64_t lower_supports, supports;
    53
    54      lower_supports = zip_source_supports(src);
    55      supports = cb(src, ud, &lower_supports, sizeof(lower_supports), ZIP_SOURCE_SUPPORTS);
    56      if (supports < 0) {
    57          zip_error_set(error,ZIP_ER_INVAL, 0); /* Initialize in case cb doesn't return valid error. */
    58          cb(src, ud, error, sizeof(*error), ZIP_SOURCE_ERROR);
    59          return NULL;
    60      }
    61
    62      if ((zs = _zip_source_new(error)) == NULL) {
    63          return NULL;
    64      }
    65
    66      zs->src = src;
    67      zs->cb.l = cb;
    68      zs->ud = ud;
    69      zs->supports = supports;
    70
    71      /* Layered sources can't support writing, since we currently have no use case. If we want to revisit this, we have to define how the two sources interact. */
    72      zs->supports &= ~(ZIP_SOURCE_SUPPORTS_WRITABLE & ~ZIP_SOURCE_SUPPORTS_SEEKABLE);
    73
    74      return zs;
    75  }
