    67  zip_source_t *
    68  _zip_source_window_new(zip_source_t *src, zip_uint64_t start, zip_int64_t length, zip_stat_t *st, zip_file_attributes_t *attributes, zip_t *source_archive, zip_uint64_t source_index, zip_error_t *error) {
    69      zip_source_t* window_source;
    70      struct window *ctx;
    71
    72      if (src == NULL || length < -1 || (source_archive == NULL && source_index != 0)) {
    73          zip_error_set(error, ZIP_ER_INVAL, 0);
    74          return NULL;
    75      }
    76
    77      if (length >= 0) {
    78          if (start + (zip_uint64_t)length < start) {
    79              zip_error_set(error, ZIP_ER_INVAL, 0);
    80              return NULL;
    81          }
    82      }
    83
    84      if ((ctx = (struct window *)malloc(sizeof(*ctx))) == NULL) {
    85          zip_error_set(error, ZIP_ER_MEMORY, 0);
    86          return NULL;
    87      }
    88
    89      ctx->start = start;
    90      if (length == -1) {
    91          ctx->end_valid = false;
    92      }
    93      else {
    94          ctx->end = start + (zip_uint64_t)length;
    95          ctx->end_valid = true;
    96      }
    97      zip_stat_init(&ctx->stat);
    98      if (attributes != NULL) {
    99          (void)memcpy_s(&ctx->attributes, sizeof(ctx->attributes), attributes, sizeof(ctx->attributes));
   100      }
   101      else {
   102          zip_file_attributes_init(&ctx->attributes);
   103      }
   104      ctx->source_archive = source_archive;
   105      ctx->source_index = source_index;
   106      zip_error_init(&ctx->error);
   107      ctx->supports = (zip_source_supports(src) & (ZIP_SOURCE_SUPPORTS_SEEKABLE | ZIP_SOURCE_SUPPORTS_REOPEN)) | (zip_source_make_command_bitmap(ZIP_SOURCE_GET_FILE_ATTRIBUTES, ZIP_SOURCE_SUPPORTS, ZIP_SOURCE_TELL, ZIP_SOURCE_FREE, -1));
   108      ctx->needs_seek = (ctx->supports & ZIP_SOURCE_MAKE_COMMAND_BITMASK(ZIP_SOURCE_SEEK)) ? true : false;
   109
   110      if (st) {
   111          if (_zip_stat_merge(&ctx->stat, st, error) < 0) {
   112              free(ctx);
   113              return NULL;
   114          }
   115      }
   116
   117      window_source = zip_source_layered_create(src, window_read, ctx, error);
   118      if (window_source != NULL) {
   119          zip_source_keep(src);
   120      }
   121      return window_source;
   122  }
