   143  static zip_int64_t
   144  window_read(zip_source_t *src, void *_ctx, void *data, zip_uint64_t len, zip_source_cmd_t cmd) {
   145      struct window *ctx;
   146      zip_int64_t ret;
   147      zip_uint64_t n, i;
   148
   149      ctx = (struct window *)_ctx;
   150
   151      switch (cmd) {
   152      case ZIP_SOURCE_CLOSE:
   153          return 0;
   154
   155      case ZIP_SOURCE_ERROR:
   156          return zip_error_to_data(&ctx->error, data, len);
   157
   158      case ZIP_SOURCE_FREE:
   159          free(ctx);
   160          return 0;
   161
   162      case ZIP_SOURCE_OPEN:
   163          if (ctx->source_archive) {
   164              zip_uint64_t offset;
   165
   166              if ((offset = _zip_file_get_offset(ctx->source_archive, ctx->source_index, &ctx->error)) == 0) {
   167                  return -1;
   168              }
   169              if (ctx->end + offset < ctx->end) {
   170                  /* zip archive data claims end of data past zip64 limits */
   171                  zip_error_set(&ctx->error, ZIP_ER_INCONS, MAKE_DETAIL_WITH_INDEX(ZIP_ER_DETAIL_CDIR_ENTRY_INVALID, ctx->source_index));
   172                  return -1;
   173              }
   174              ctx->start += offset;
   175              ctx->end += offset;
   176              ctx->source_archive = NULL;
   177          }
   178
   179          if (!ctx->needs_seek) {
   180              DEFINE_BYTE_ARRAY(b, BUFSIZE);
   181
   182              if (!byte_array_init(b, BUFSIZE)) {
   183                  zip_error_set(&ctx->error, ZIP_ER_MEMORY, 0);
   184                  return -1;
   185              }
   186
   187              for (n = 0; n < ctx->start; n += (zip_uint64_t)ret) {
   188                  i = (ctx->start - n > BUFSIZE ? BUFSIZE : ctx->start - n);
   189                  if ((ret = zip_source_read(src, b, i)) < 0) {
   190                      zip_error_set_from_source(&ctx->error, src);
   191                      byte_array_fini(b);
   192                      return -1;
   193                  }
   194                  if (ret == 0) {
   195                      zip_error_set(&ctx->error, ZIP_ER_EOF, 0);
   196                      byte_array_fini(b);
   197                      return -1;
   198                  }
   199              }
   200
   201              byte_array_fini(b);
   202          }
   203
   204          ctx->offset = ctx->start;
   205          return 0;
   206
   207      case ZIP_SOURCE_READ:
   208          if (ctx->end_valid && len > ctx->end - ctx->offset) {
   209              len = ctx->end - ctx->offset;
   210          }
   211
   212          if (len == 0) {
   213              return 0;
   214          }
   215
   216          if (ctx->needs_seek) {
   217              if (zip_source_seek(src, (zip_int64_t)ctx->offset, SEEK_SET) < 0) {
   218                  zip_error_set_from_source(&ctx->error, src);
   219                  return -1;
   220              }
   221          }
   222
   223          if ((ret = zip_source_read(src, data, len)) < 0) {
   224              zip_error_set(&ctx->error, ZIP_ER_EOF, 0);
   225              return -1;
   226          }
   227
   228          ctx->offset += (zip_uint64_t)ret;
   229
   230          if (ret == 0) {
   231              if (ctx->end_valid && ctx->offset < ctx->end) {
   232                  zip_error_set(&ctx->error, ZIP_ER_EOF, 0);
   233                  return -1;
   234              }
   235          }
   236          return ret;
   237
   238      case ZIP_SOURCE_SEEK: {
   239          zip_int64_t new_offset;
   240
   241          if (!ctx->end_valid) {
   242              zip_source_args_seek_t *args = ZIP_SOURCE_GET_ARGS(zip_source_args_seek_t, data, len, &ctx->error);
   243
   244              if (args == NULL) {
   245                  return -1;
   246              }
   247              if (args->whence == SEEK_END) {
   248                  if (zip_source_seek(src, args->offset, args->whence) < 0) {
   249                      zip_error_set_from_source(&ctx->error, src);
   250                      return -1;
   251                  }
   252                  new_offset = zip_source_tell(src);
   253                  if (new_offset < 0) {
   254                      zip_error_set_from_source(&ctx->error, src);
   255                      return -1;
   256                  }
   257                  if ((zip_uint64_t)new_offset < ctx->start) {
   258                      zip_error_set(&ctx->error, ZIP_ER_INVAL, 0);
   259                      (void)zip_source_seek(src, (zip_int64_t)ctx->offset, SEEK_SET);
   260                      return -1;
